import { openai } from "@ai-sdk/openai";
import { streamText, tool } from "ai";
import { z } from "zod";

import { getMcpTools } from "@/lib/mcp";
import { queryIncidents } from "@/lib/incidents";

export const runtime = "nodejs";
export const maxDuration = 60;

const SYSTEM = `You are the on-call operations copilot. Use the incident tools to answer
questions about open incidents and never invent ticket numbers. When asked to take an
action, describe the change and call the matching tool.`;

export async function POST(req: Request) {
  const { messages } = await req.json();
  const mcp = await getMcpTools();

  const result = streamText({
    model: openai("gpt-4o"),
    system: SYSTEM,
    messages,
    maxSteps: 8,
    tools: {
      ...mcp.tools,
      listOpenIncidents: tool({
        description: "List incidents that are currently open, optionally filtered by service",
        parameters: z.object({ service: z.string().optional() }),
        execute: async ({ service }) => queryIncidents({ status: "open", service }),
      }),
      acknowledgeIncident: tool({
        description: "Acknowledge an incident on behalf of the current on-call engineer",
        parameters: z.object({ id: z.string(), note: z.string().max(500) }),
        execute: async ({ id, note }) => ({ id, acknowledged: true, note }),
      }),
    },
    onFinish: async () => {
      await mcp.close();
    },
  });

  return result.toDataStreamResponse();
}

