import { experimental_createMCPClient as createMCPClient } from "ai";
import { Experimental_StdioMCPTransport as StdioMCPTransport } from "ai/mcp-stdio";
import { readFile } from "node:fs/promises";
import path from "node:path";

type ServerConfig = {
  command?: string;
  args?: string[];
  url?: string;
  env?: Record<string, string>;
  disabled?: boolean;
};

type McpConfig = { mcpServers: Record<string, ServerConfig> };

export async function getMcpTools() {
  const raw = await readFile(path.join(process.cwd(), "mcp-servers.json"), "utf8");
  const config = JSON.parse(raw) as McpConfig;
  const clients = [];
  let tools: Record<string, unknown> = {};

  for (const [name, server] of Object.entries(config.mcpServers)) {
    if (server.disabled) continue;
    const client = server.url
      ? await createMCPClient({ transport: { type: "sse", url: server.url } })
      : await createMCPClient({
          transport: new StdioMCPTransport({
            command: server.command ?? "npx",
            args: server.args ?? [],
            env: { ...process.env, ...(server.env ?? {}) } as Record<string, string>,
          }),
        });
    clients.push(client);
    const serverTools = await client.tools();
    tools = { ...tools, ...prefixKeys(name, serverTools) };
  }

  return {
    tools,
    close: async () => {
      await Promise.all(clients.map((c) => c.close()));
    },
  };
}

function prefixKeys<T>(prefix: string, obj: Record<string, T>): Record<string, T> {
  const out: Record<string, T> = {};
  for (const [k, v] of Object.entries(obj)) out[`${prefix}_${k}`] = v;
  return out;
}

