import { z } from "zod";

const Incident = z.object({
  id: z.string(),
  service: z.string(),
  status: z.enum(["open", "acknowledged", "resolved"]),
  openedAt: z.string(),
  summary: z.string(),
});

export type Incident = z.infer<typeof Incident>;

const INCIDENT_API = process.env.INCIDENT_API_URL ?? "http://incidents.internal:9000";

export async function queryIncidents(filter: { status?: string; service?: string }): Promise<Incident[]> {
  const params = new URLSearchParams();
  if (filter.status) params.set("status", filter.status);
  if (filter.service) params.set("service", filter.service);
  const res = await fetch(`${INCIDENT_API}/incidents?${params.toString()}`, {
    headers: { accept: "application/json" },
    cache: "no-store",
  });
  if (!res.ok) {
    throw new Error(`incident api returned ${res.status}`);
  }
  const body = await res.json();
  return z.array(Incident).parse(body.items ?? []);
}

