import json
import logging
import os

import boto3

log = logging.getLogger()
log.setLevel(os.environ.get("LOG_LEVEL", "INFO"))
table = boto3.resource("dynamodb").Table(os.environ["ORDERS_TABLE"])


def _param(event, name):
    for p in event.get("parameters", []):
        if p.get("name") == name:
            return p.get("value")
    return None


def lambda_handler(event, context):
    api_path = event.get("apiPath")
    order_id = _param(event, "orderId")
    log.info("action %s for order %s", api_path, order_id)
    if api_path == "/orders/{orderId}/status":
        item = table.get_item(Key={"order_id": order_id}).get("Item") or {}
        body = {"orderId": order_id, "status": item.get("status", "unknown")}
    elif api_path == "/orders/{orderId}/reship":
        table.update_item(
            Key={"order_id": order_id},
            UpdateExpression="SET #s = :s",
            ExpressionAttributeNames={"#s": "status"},
            ExpressionAttributeValues={":s": "reship-requested"},
        )
        body = {"orderId": order_id, "status": "reship-requested"}
    else:
        body = {"error": f"unknown path {api_path}"}
    return {
        "messageVersion": "1.0",
        "response": {
            "actionGroup": event.get("actionGroup"),
            "apiPath": api_path,
            "httpMethod": event.get("httpMethod"),
            "httpStatusCode": 200,
            "responseBody": {"application/json": {"body": json.dumps(body)}},
        },
    }

