using InventoryAssistant.Plugins;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.ChatCompletion;
using Microsoft.SemanticKernel.Connectors.OpenAI;

var config = new ConfigurationBuilder()
    .AddJsonFile("appsettings.json", optional: false)
    .AddUserSecrets<Program>()
    .AddEnvironmentVariables()
    .Build();

var modelId = config["OpenAI:Model"] ?? "gpt-4o-mini";
var apiKey = config["OpenAI:ApiKey"] ?? throw new InvalidOperationException("OpenAI:ApiKey is not configured");

var builder = Kernel.CreateBuilder();
builder.Services.AddLogging(l => l.AddConsole().SetMinimumLevel(LogLevel.Warning));
builder.AddOpenAIChatCompletion(modelId, apiKey);
builder.Plugins.AddFromType<InventoryPlugin>("inventory");
builder.Plugins.AddFromType<SupplierPlugin>("suppliers");

Kernel kernel = builder.Build();
var chat = kernel.GetRequiredService<IChatCompletionService>();

var settings = new OpenAIPromptExecutionSettings
{
    ToolCallBehavior = ToolCallBehavior.AutoInvokeKernelFunctions,
    Temperature = 0,
};

var history = new ChatHistory(
    "You are a warehouse inventory assistant. Answer using the inventory and supplier " +
    "plugins. If a reorder is requested, confirm the SKU and quantity before placing it.");

Console.WriteLine("Inventory assistant ready. Type 'exit' to quit.");
while (true)
{
    Console.Write("> ");
    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Trim().Equals("exit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }
    history.AddUserMessage(input);
    var reply = await chat.GetChatMessageContentAsync(history, settings, kernel);
    history.AddAssistantMessage(reply.Content ?? string.Empty);
    Console.WriteLine(reply.Content);
}

