using System.ComponentModel;
using Microsoft.SemanticKernel;

namespace InventoryAssistant.Plugins;

public sealed class InventoryPlugin
{
    private static readonly Dictionary<string, int> Stock = new()
    {
        ["SKU-1001"] = 42,
        ["SKU-1002"] = 0,
        ["SKU-2040"] = 7,
    };

    [KernelFunction("get_stock_level")]
    [Description("Returns the number of units on hand for a SKU")]
    public int GetStockLevel([Description("The SKU to look up")] string sku)
    {
        return Stock.TryGetValue(sku.ToUpperInvariant(), out var qty) ? qty : -1;
    }

    [KernelFunction("list_low_stock")]
    [Description("Lists SKUs whose on hand quantity is below the threshold")]
    public IEnumerable<string> ListLowStock([Description("Threshold quantity")] int threshold = 10)
    {
        return Stock.Where(kv => kv.Value < threshold).Select(kv => $"{kv.Key}: {kv.Value}");
    }

    [KernelFunction("adjust_stock")]
    [Description("Adjusts the on hand quantity for a SKU by a positive or negative delta")]
    public string AdjustStock(string sku, int delta)
    {
        var key = sku.ToUpperInvariant();
        if (!Stock.ContainsKey(key))
        {
            return $"unknown sku {key}";
        }
        Stock[key] = Math.Max(0, Stock[key] + delta);
        return $"{key} now at {Stock[key]}";
    }
}

