using System.ComponentModel;
using Microsoft.SemanticKernel;

namespace InventoryAssistant.Plugins;

public sealed class SupplierPlugin
{
    private readonly HttpClient _http = new() { BaseAddress = new Uri("http://suppliers.internal:8080/") };

    [KernelFunction("lead_time_days")]
    [Description("Returns the supplier lead time in days for a SKU")]
    public async Task<int> LeadTimeDaysAsync(string sku)
    {
        using var response = await _http.GetAsync($"skus/{Uri.EscapeDataString(sku)}/lead-time");
        if (!response.IsSuccessStatusCode)
        {
            return -1;
        }
        var text = await response.Content.ReadAsStringAsync();
        return int.TryParse(text, out var days) ? days : -1;
    }

    [KernelFunction("place_reorder")]
    [Description("Places a purchase order for the SKU and quantity and returns the PO number")]
    public async Task<string> PlaceReorderAsync(string sku, int quantity)
    {
        var payload = new StringContent("{\"sku\":\"" + sku + "\",\"quantity\":" + quantity + "}");
        payload.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/json");
        using var response = await _http.PostAsync("purchase-orders", payload);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }
}

