package main

import (
	"context"
	"encoding/json"
	"net/http"
	"os"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/rs/zerolog"

	"example.com/changelog-agent/agent"
)

type askRequest struct {
	Question string `json:"question"`
}

type askResponse struct {
	Answer string `json:"answer"`
}

func main() {
	log := zerolog.New(os.Stdout).With().Timestamp().Logger()
	runner, err := agent.New(context.Background(), os.Getenv("CHANGELOG_DIR"))
	if err != nil {
		log.Fatal().Err(err).Msg("agent init failed")
	}

	r := chi.NewRouter()
	r.Use(middleware.RequestID, middleware.Recoverer, middleware.Timeout(60*time.Second))
	r.Get("/healthz", func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusNoContent) })
	r.Post("/ask", func(w http.ResponseWriter, req *http.Request) {
		var in askRequest
		if err := json.NewDecoder(req.Body).Decode(&in); err != nil || in.Question == "" {
			http.Error(w, "question required", http.StatusBadRequest)
			return
		}
		answer, err := runner.Ask(req.Context(), in.Question)
		if err != nil {
			log.Error().Err(err).Msg("ask failed")
			http.Error(w, "agent error", http.StatusBadGateway)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(askResponse{Answer: answer})
	})

	addr := ":" + envOr("PORT", "8080")
	log.Info().Str("addr", addr).Msg("listening")
	if err := http.ListenAndServe(addr, r); err != nil {
		log.Fatal().Err(err).Msg("server stopped")
	}
}

func envOr(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

