package agent

import (
	"context"
	"fmt"

	"github.com/tmc/langchaingo/agents"
	"github.com/tmc/langchaingo/chains"
	"github.com/tmc/langchaingo/llms/openai"
	"github.com/tmc/langchaingo/tools"

	ctools "example.com/changelog-agent/tools"
)

// Runner wraps a one-shot ReAct style agent over changelog tools.
type Runner struct {
	executor *agents.Executor
}

func New(ctx context.Context, changelogDir string) (*Runner, error) {
	llm, err := openai.New(openai.WithModel("gpt-4o-mini"))
	if err != nil {
		return nil, fmt.Errorf("llm: %w", err)
	}
	toolset := []tools.Tool{
		ctools.NewChangelogSearch(changelogDir),
		ctools.NewVersionDiff(changelogDir),
		tools.Calculator{},
	}
	a := agents.NewOneShotAgent(llm, toolset, agents.WithMaxIterations(5))
	exec := agents.NewExecutor(a)
	return &Runner{executor: exec}, nil
}

func (r *Runner) Ask(ctx context.Context, question string) (string, error) {
	out, err := chains.Run(ctx, r.executor, question)
	if err != nil {
		return "", err
	}
	return out, nil
}

