package tools

import (
	"context"
	"os"
	"path/filepath"
	"strings"
)

type ChangelogSearch struct{ dir string }

func NewChangelogSearch(dir string) ChangelogSearch { return ChangelogSearch{dir: dir} }

func (t ChangelogSearch) Name() string { return "changelog_search" }

func (t ChangelogSearch) Description() string {
	return "Searches release notes for a keyword and returns matching lines with their version"
}

func (t ChangelogSearch) Call(_ context.Context, input string) (string, error) {
	needle := strings.ToLower(strings.TrimSpace(input))
	var hits []string
	entries, err := os.ReadDir(t.dir)
	if err != nil {
		return "", err
	}
	for _, e := range entries {
		if e.IsDir() || filepath.Ext(e.Name()) != ".md" {
			continue
		}
		data, err := os.ReadFile(filepath.Join(t.dir, e.Name()))
		if err != nil {
			continue
		}
		for _, line := range strings.Split(string(data), "\n") {
			if strings.Contains(strings.ToLower(line), needle) {
				hits = append(hits, e.Name()+": "+strings.TrimSpace(line))
			}
		}
	}
	if len(hits) == 0 {
		return "no matches", nil
	}
	return strings.Join(hits, "\n"), nil
}

type VersionDiff struct{ dir string }

func NewVersionDiff(dir string) VersionDiff { return VersionDiff{dir: dir} }

func (t VersionDiff) Name() string { return "version_diff" }

func (t VersionDiff) Description() string {
	return "Given 'vA..vB' returns the release note headings between the two versions"
}

func (t VersionDiff) Call(_ context.Context, input string) (string, error) {
	parts := strings.SplitN(strings.TrimSpace(input), "..", 2)
	if len(parts) != 2 {
		return "expected input like v1.2.0..v1.4.0", nil
	}
	return "headings between " + parts[0] + " and " + parts[1] + " are not indexed yet", nil
}

