#!/usr/bin/env node
import { Command } from "commander";
import { readFileSync } from "node:fs";
import { parse } from "yaml";

import { rules } from "./rules/index.js";

const program = new Command();
program
  .name("manifest-lint")
  .description("Validate deployment manifests against team rules")
  .argument("<files...>", "manifest files to check")
  .option("--json", "emit findings as JSON")
  .action((files: string[], opts: { json?: boolean }) => {
    const findings = [];
    for (const file of files) {
      const doc = parse(readFileSync(file, "utf8"));
      for (const rule of rules) {
        for (const problem of rule.check(doc)) {
          findings.push({ file, rule: rule.id, message: problem });
        }
      }
    }
    if (opts.json) {
      process.stdout.write(JSON.stringify(findings, null, 2) + "\n");
    } else {
      for (const f of findings) process.stdout.write(`${f.file}: [${f.rule}] ${f.message}\n`);
    }
    process.exitCode = findings.length ? 1 : 0;
  });

program.parse();

