package com.example.helpdesk;

import org.springframework.ai.chat.client.ChatClient;
import org.springframework.ai.chat.client.advisor.MessageChatMemoryAdvisor;
import org.springframework.ai.chat.memory.InMemoryChatMemory;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class AssistantController {

    private static final String SYSTEM = """
        You are the help desk assistant. Use the ticket tools to answer questions about
        tickets and to change their status. Never change a ticket the caller does not own.
        Keep answers under 120 words.
        """;

    private final ChatClient chatClient;
    private final TicketTools ticketTools;

    public AssistantController(ChatClient.Builder builder, TicketTools ticketTools) {
        this.ticketTools = ticketTools;
        this.chatClient = builder
            .defaultSystem(SYSTEM)
            .defaultAdvisors(new MessageChatMemoryAdvisor(new InMemoryChatMemory()))
            .build();
    }

    public record AskRequest(String message) {}

    public record AskResponse(String reply) {}

    @PostMapping("/assistant/ask")
    public AskResponse ask(@RequestHeader("X-User") String user, @RequestBody AskRequest request) {
        String reply = chatClient.prompt()
            .user(u -> u.text("User {user} asks: {message}").param("user", user).param("message", request.message()))
            .tools(ticketTools)
            .advisors(a -> a.param("chat_memory_conversation_id", user))
            .call()
            .content();
        return new AskResponse(reply);
    }
}

