package com.example.helpdesk;

import java.util.List;

import org.springframework.ai.tool.annotation.Tool;
import org.springframework.ai.tool.annotation.ToolParam;
import org.springframework.stereotype.Component;

@Component
public class TicketTools {

    private final TicketRepository repository;

    public TicketTools(TicketRepository repository) {
        this.repository = repository;
    }

    @Tool(description = "List the open tickets owned by a user")
    public List<Ticket> listOpenTickets(@ToolParam(description = "login of the owner") String owner) {
        return repository.findByOwnerAndStatus(owner, "open");
    }

    @Tool(description = "Get one ticket by id")
    public Ticket getTicket(@ToolParam(description = "ticket id such as HD-1042") String id) {
        return repository.findById(id).orElseThrow(() -> new IllegalArgumentException("no ticket " + id));
    }

    @Tool(description = "Change the status of a ticket. Allowed values: open, waiting, closed")
    public String setStatus(String id, String status, @ToolParam(description = "login of the caller") String caller) {
        Ticket ticket = getTicket(id);
        if (!ticket.getOwner().equals(caller)) {
            return "refused: " + caller + " does not own " + id;
        }
        if (!List.of("open", "waiting", "closed").contains(status)) {
            return "refused: unknown status " + status;
        }
        ticket.setStatus(status);
        repository.save(ticket);
        return id + " is now " + status;
    }
}

