from __future__ import annotations

import json
import os
import re
from pathlib import Path

NOTES_DIR = Path(os.environ.get("NOTES_DIR", "notes"))

TOOL_SPECS = [
    {
        "type": "function",
        "function": {
            "name": "list_versions",
            "description": "List the versions that have release notes, newest first",
            "parameters": {"type": "object", "properties": {}, "required": []},
        },
    },
    {
        "type": "function",
        "function": {
            "name": "read_notes",
            "description": "Read the release notes for one version",
            "parameters": {
                "type": "object",
                "properties": {"version": {"type": "string", "description": "e.g. 2.14.0"}},
                "required": ["version"],
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "grep_notes",
            "description": "Search all release notes for a regular expression",
            "parameters": {
                "type": "object",
                "properties": {"pattern": {"type": "string"}},
                "required": ["pattern"],
            },
        },
    },
]


def list_versions() -> list[str]:
    versions = [p.stem for p in NOTES_DIR.glob("*.md")]
    return sorted(versions, key=lambda v: [int(x) for x in v.split(".") if x.isdigit()], reverse=True)


def read_notes(version: str) -> str:
    path = NOTES_DIR / f"{version}.md"
    if not path.is_file():
        return f"no notes for {version}"
    return path.read_text(encoding="utf-8")[:8000]


def grep_notes(pattern: str) -> list[str]:
    rx = re.compile(pattern, re.IGNORECASE)
    hits = []
    for path in NOTES_DIR.glob("*.md"):
        for n, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
            if rx.search(line):
                hits.append(f"{path.stem}:{n}: {line.strip()}")
    return hits[:50]


def run_tool(name: str, args: dict) -> str:
    handlers = {"list_versions": list_versions, "read_notes": read_notes, "grep_notes": grep_notes}
    if name not in handlers:
        return json.dumps({"error": f"unknown tool {name}"})
    try:
        return json.dumps(handlers[name](**args))
    except Exception as exc:  # noqa: BLE001
        return json.dumps({"error": str(exc)})

