import { run } from "@openai/agents";

import { frontDesk } from "./agents.js";
import { nextMessage, reply } from "./queue.js";

async function main() {
  for (;;) {
    const msg = await nextMessage();
    if (!msg) continue;
    try {
      const result = await run(frontDesk, msg.text, { maxTurns: 10 });
      await reply(msg.id, result.finalOutput ?? "Sorry, I could not work that out.");
    } catch (err) {
      console.error("run failed", msg.id, err);
      await reply(msg.id, "Something went wrong, a colleague will follow up.");
    }
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

