import pg from "pg";

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });

export type Order = {
  number: string;
  deliveredAt: string | null;
  items: { sku: string; name: string; qty: number }[];
};

export async function findOrder(orderNumber: string): Promise<Order | { error: string }> {
  const { rows } = await pool.query(
    "select number, delivered_at, items from orders where number = $1",
    [orderNumber],
  );
  if (rows.length === 0) return { error: "no such order" };
  return { number: rows[0].number, deliveredAt: rows[0].delivered_at, items: rows[0].items };
}

export async function openReturn(orderNumber: string, sku: string, reason: string) {
  const { rows } = await pool.query(
    "insert into returns (order_number, sku, reason) values ($1, $2, $3) returning id",
    [orderNumber, sku, reason],
  );
  return { returnId: rows[0].id, status: "opened" };
}

