import pg from "pg";

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });

export type Inbound = { id: string; text: string };

export async function nextMessage(): Promise<Inbound | null> {
  const { rows } = await pool.query(
    "update messages set claimed_at = now() where id = (select id from messages where claimed_at is null order by created_at limit 1 for update skip locked) returning id, body",
  );
  if (rows.length === 0) {
    await new Promise((r) => setTimeout(r, 1000));
    return null;
  }
  return { id: rows[0].id, text: rows[0].body };
}

export async function reply(id: string, text: string): Promise<void> {
  await pool.query("insert into replies (message_id, body) values ($1, $2)", [id, text]);
}

