from flask import Blueprint, abort, jsonify, request

from models import ROLES, Agent, db

agents_bp = Blueprint("agents", __name__)


@agents_bp.get("/")
def list_agents():
    query = Agent.query
    if role := request.args.get("role"):
        query = query.filter_by(role=role)
    if office := request.args.get("office_id"):
        query = query.filter_by(office_id=int(office))
    return jsonify([a.to_dict() for a in query.order_by(Agent.last_name).all()])


@agents_bp.post("/")
def create_agent():
    body = request.get_json(force=True)
    if body.get("role", "agent") not in ROLES:
        abort(400, description="unknown role")
    agent = Agent(
        first_name=body["first_name"],
        last_name=body["last_name"],
        license_number=body["license_number"],
        role=body.get("role", "agent"),
        office_id=body.get("office_id"),
        supervisor_id=body.get("supervisor_id"),
    )
    db.session.add(agent)
    db.session.commit()
    return jsonify(agent.to_dict()), 201


@agents_bp.get("/<int:agent_id>")
def get_agent(agent_id: int):
    return jsonify(Agent.query.get_or_404(agent_id).to_dict())


@agents_bp.put("/<int:agent_id>/supervisor")
def assign_supervisor(agent_id: int):
    agent = Agent.query.get_or_404(agent_id)
    supervisor = Agent.query.get_or_404(request.get_json(force=True)["supervisor_id"])
    if not supervisor.is_supervisor:
        abort(400, description="target is not a supervisor")
    agent.supervisor = supervisor
    db.session.commit()
    return jsonify(agent.to_dict())


@agents_bp.delete("/<int:agent_id>")
def delete_agent(agent_id: int):
    agent = Agent.query.get_or_404(agent_id)
    db.session.delete(agent)
    db.session.commit()
    return "", 204

