        headers["Accept"] = "application/json"
        if self.configuration.api_key:
            headers["X-Api-Key"] = self.configuration.api_key
        encoded = json.dumps(body).encode("utf-8") if body is not None else None
        if encoded is not None:
            headers["Content-Type"] = "application/json"
        response = self._pool.request(method, url, body=encoded, headers=headers)
        if response.status >= 400:
            raise ApiException(response.status, response.data.decode("utf-8", "replace"))
        return json.loads(response.data) if response.data else None

