from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from langchain_text_splitters import MarkdownHeaderTextSplitter, RecursiveCharacterTextSplitter

HEADERS = [("#", "h1"), ("##", "h2"), ("###", "h3")]


@dataclass(frozen=True)
class Chunk:
    source: str
    index: int
    text: str
    headers: dict[str, str]


def chunk_text(text: str, *, source: str = "<memory>", size: int = 800, overlap: int = 120) -> list[Chunk]:
    by_header = MarkdownHeaderTextSplitter(headers_to_split_on=HEADERS, strip_headers=False)
    recursive = RecursiveCharacterTextSplitter(chunk_size=size, chunk_overlap=overlap)
    chunks: list[Chunk] = []
    for section in by_header.split_text(text):
        for piece in recursive.split_text(section.page_content):
            chunks.append(Chunk(source=source, index=len(chunks), text=piece, headers=dict(section.metadata)))
    return chunks


def chunk_file(path: Path, **kwargs) -> list[Chunk]:
    return chunk_text(path.read_text(encoding="utf-8"), source=str(path), **kwargs)

