from __future__ import annotations

import json
from pathlib import Path

import click

from chunker.split import chunk_file


@click.command()
@click.argument("paths", nargs=-1, type=click.Path(exists=True, path_type=Path))
@click.option("--size", default=800, show_default=True, help="target characters per chunk")
@click.option("--overlap", default=120, show_default=True)
@click.option("--out", type=click.Path(path_type=Path), default=Path("chunks.jsonl"))
def main(paths: tuple[Path, ...], size: int, overlap: int, out: Path) -> None:
    """Write one JSON line per chunk for every markdown file given."""
    count = 0
    with out.open("w", encoding="utf-8") as handle:
        for path in paths:
            files = sorted(path.rglob("*.md")) if path.is_dir() else [path]
            for file in files:
                for chunk in chunk_file(file, size=size, overlap=overlap):
                    handle.write(json.dumps(chunk.__dict__, ensure_ascii=False) + "\n")
                    count += 1
    click.echo(f"wrote {count} chunks to {out}")


if __name__ == "__main__":
    main()

