from __future__ import annotations

import re
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

import yaml

_RULES = Path(__file__).with_name("regexes.yaml")


@dataclass(frozen=True)
class UserAgent:
    family: str
    major: str | None
    minor: str | None
    os: str | None
    device: str | None
    is_bot: bool

    def __str__(self) -> str:
        version = ".".join(v for v in (self.major, self.minor) if v)
        return f"{self.family} {version}".strip()


@lru_cache(maxsize=1)
def _rules() -> dict:
    with _RULES.open(encoding="utf-8") as handle:
        raw = yaml.safe_load(handle)
    compiled = {}
    for section in ("browsers", "os", "devices", "bots"):
        compiled[section] = [(re.compile(r["regex"]), r.get("family", "$1")) for r in raw.get(section, [])]
    return compiled


def _first(section: str, ua: str) -> tuple[str | None, re.Match | None]:
    for pattern, family in _rules()[section]:
        m = pattern.search(ua)
        if m:
            name = family.replace("$1", m.group(1)) if "$1" in family and m.groups() else family
            return name, m
    return None, None


@lru_cache(maxsize=4096)
def parse(user_agent: str) -> UserAgent:
    ua = user_agent.strip()[:1024]
    bot, _ = _first("bots", ua)
    if bot:
        return UserAgent(bot, None, None, None, None, True)
    family, m = _first("browsers", ua)
    major = m.group(2) if m and m.lastindex and m.lastindex >= 2 else None
    minor = m.group(3) if m and m.lastindex and m.lastindex >= 3 else None
    os_name, _ = _first("os", ua)
    device, _ = _first("devices", ua)
    return UserAgent(family or "Other", major, minor, os_name, device, False)

