const { App } = require("@slack/bolt");
const cron = require("node-cron");

const { openStandup, recordAnswer, postSummary } = require("./standup");

const app = new App({
  token: process.env.SLACK_BOT_TOKEN,
  signingSecret: process.env.SLACK_SIGNING_SECRET,
  appToken: process.env.SLACK_APP_TOKEN,
  socketMode: true,
});

const CHANNEL = process.env.STANDUP_CHANNEL || "#team-standup";

app.command("/standup", async ({ ack, body, client }) => {
  await ack();
  await openStandup(client, body.user_id);
});

app.view("standup_submit", async ({ ack, body, view, client }) => {
  await ack();
  const answers = {
    yesterday: view.state.values.yesterday.text.value,
    today: view.state.values.today.text.value,
    blockers: view.state.values.blockers.text.value,
  };
  await recordAnswer(body.user.id, answers);
  await client.chat.postEphemeral({ channel: CHANNEL, user: body.user.id, text: "Thanks, recorded." });
});

cron.schedule("0 9 * * 1-5", async () => {
  await app.client.chat.postMessage({ channel: CHANNEL, text: "Standup time. Run /standup to submit yours." });
});

cron.schedule("30 10 * * 1-5", async () => {
  await postSummary(app.client, CHANNEL);
});

(async () => {
  await app.start();
  console.log("standup bot running");
})();

