const { Pool } = require("pg");

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

async function openStandup(client, userId) {
  await client.views.open({
    trigger_id: undefined,
    view: {
      type: "modal",
      callback_id: "standup_submit",
      title: { type: "plain_text", text: "Daily standup" },
      submit: { type: "plain_text", text: "Submit" },
      blocks: ["yesterday", "today", "blockers"].map((id) => ({
        type: "input",
        block_id: id,
        label: { type: "plain_text", text: id },
        element: { type: "plain_text_input", action_id: "text", multiline: true },
        optional: id === "blockers",
      })),
    },
  });
}

async function recordAnswer(userId, answers) {
  await pool.query(
    "insert into standups (user_id, day, yesterday, today, blockers) values ($1, current_date, $2, $3, $4) on conflict (user_id, day) do update set yesterday = $2, today = $3, blockers = $4",
    [userId, answers.yesterday, answers.today, answers.blockers],
  );
}

async function postSummary(client, channel) {
  const { rows } = await pool.query("select user_id, today, blockers from standups where day = current_date order by user_id");
  if (rows.length === 0) {
    await client.chat.postMessage({ channel, text: "No standups submitted today." });
    return;
  }
  const lines = rows.map((r) => `<@${r.user_id}>: ${r.today}${r.blockers ? ` (blocked: ${r.blockers})` : ""}`);
  await client.chat.postMessage({ channel, text: ["Today's standup:", ...lines].join("\n") });
}

module.exports = { openStandup, recordAnswer, postSummary };

