from __future__ import annotations

import base64
import hashlib
import hmac
import json
import time

import requests

PUBLIC_URL = "https://api.gemini.com"
SANDBOX_URL = "https://api.sandbox.gemini.com"


class GeminiClient:
    """Thin wrapper over the exchange's public and private endpoints."""

    def __init__(self, api_key: str | None = None, api_secret: str | None = None, sandbox: bool = False) -> None:
        self.base_url = SANDBOX_URL if sandbox else PUBLIC_URL
        self.api_key = api_key
        self.api_secret = api_secret.encode() if api_secret else None
        self.session = requests.Session()
        self.session.headers["User-Agent"] = "gemini-python/1.8.2"

    # public endpoints -----------------------------------------------------
    def symbols(self) -> list[str]:
        return self._get("/v1/symbols")

    def ticker(self, symbol: str) -> dict:
        return self._get(f"/v2/ticker/{symbol.lower()}")

    def order_book(self, symbol: str, limit: int = 50) -> dict:
        return self._get(f"/v1/book/{symbol.lower()}", params={"limit_bids": limit, "limit_asks": limit})

    # private endpoints ----------------------------------------------------
    def balances(self) -> list[dict]:
        return self._post("/v1/balances")

    def new_order(self, symbol: str, amount: str, price: str, side: str) -> dict:
        payload = {"symbol": symbol, "amount": amount, "price": price, "side": side, "type": "exchange limit"}
        return self._post("/v1/order/new", payload)

    def _get(self, path: str, params: dict | None = None):
        response = self.session.get(self.base_url + path, params=params, timeout=10)
        response.raise_for_status()
        return response.json()

    def _post(self, path: str, payload: dict | None = None):
        if not self.api_key or not self.api_secret:
            raise RuntimeError("private endpoints need an api key and secret")
        body = {"request": path, "nonce": str(int(time.time() * 1000)), **(payload or {})}
        encoded = base64.b64encode(json.dumps(body).encode())
        signature = hmac.new(self.api_secret, encoded, hashlib.sha384).hexdigest()
        headers = {
            "Content-Type": "text/plain",
            "X-GEMINI-APIKEY": self.api_key,
            "X-GEMINI-PAYLOAD": encoded.decode(),
            "X-GEMINI-SIGNATURE": signature,
            "Cache-Control": "no-cache",
        }
        response = self.session.post(self.base_url + path, headers=headers, timeout=10)
        response.raise_for_status()
        return response.json()

