const { bundle } = require("lightningcss");
const fs = require("node:fs");
const path = require("node:path");

const entry = path.join(__dirname, "..", "src", "index.css");
const outDir = path.join(__dirname, "..", "dist");
const watch = process.argv.includes("--watch");

function build() {
  const { code } = bundle({ filename: entry, minify: true, sourceMap: false });
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(path.join(outDir, "copilot.css"), code);
  console.log(`built dist/copilot.css (${code.length} bytes)`);
}

build();
if (watch) {
  fs.watch(path.join(__dirname, "..", "src"), { recursive: true }, () => {
    try {
      build();
    } catch (err) {
      console.error(err.message);
    }
  });
}
